// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"#include "Common/ComputeRenderPass.h"class CAutoExposureStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_AutoExposure;	CAutoExposureStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_passLuminanceInitial(&graphicsPipeline)		, m_passAutoExposure(&graphicsPipeline)		, m_passMeterHistogram(&graphicsPipeline, CComputeRenderPass::eFlags_ReflectConstantBuffersFromShader)	{		for (auto& pass : m_passLuminanceIteration)			pass.SetGraphicsPipeline(&graphicsPipeline);	}	bool IsStageActive(EShaderRenderingFlags flags) const final	{		return RenderView()->GetCurrentEye() != CCamera::eEye_Right;	}	void Execute();private:	void MeasureLuminance();	void AdjustExposure();	//! Scene-referred AUTO metering (SceneReferredSpec.md D2/D7, decisions/s1-auto-mode.md part 1	//! approach A). Two-phase, non-blocking readback of the 1x1 measure target, so the camera can	//! run its exposure loop in EV on the CPU where a camera's controls live. Only ever issued on	//! the scene-referred path.	void UpdateSceneReferredMeterReadback();	//! The camera's metering histogram (S8, decisions/s8-metering.md approach A): a 64-bin log2	//! luminance histogram of the quarter-res exposed frame, accumulated with the camera's	//! metering mask into a 64x1 uint UAV. Clears and dispatches; the readback above then hands	//! the bins to the camera, which takes the log-mean of a percentile band of them.	void ExecuteMeterHistogram();	//! Creates the 64x1 accumulation target on demand and returns false if it could not be had.	bool EnsureMeterHistogramTexture();	//! Drops every published meter value so the camera cannot keep metering off a sample from	//! before the switch was flipped, or from the other metering path.	void RetireSceneReferredMeter();private:	CFullscreenPass m_passLuminanceInitial;	CFullscreenPass m_passLuminanceIteration[NUM_HDR_TONEMAP_TEXTURES];	CFullscreenPass m_passAutoExposure;	CComputeRenderPass m_passMeterHistogram;	// The histogram's accumulation target: 64x1, R32 typeless underneath (FT_USAGE_UAV_RWTEXTURE),	// bound through a DXGI_FORMAT_R32_UINT typed UAV so InterlockedAdd is legal, and carrying	// FT_STAGE_READBACK so the two-phase download below needs no copy pass and no staging	// resource of its own. The engine's ETEX_Format list has no uint entry, which is why the view	// is built by hand - the precedent is m_pTexLinearDepthFixupUAV in GraphicsPipeline.cpp.	_smart_ptr<CTexture> m_pTexMeterHistogram;	ResourceViewHandle   m_meterHistogramUAV = EDefaultResourceViews::UnorderedAccess;	bool                 m_bMeterHistogramValid = false;	// The creation failure below is retried every frame the meter runs, so the line that reports it	// has to be latched or it becomes a per-frame log. Cleared when a target is created, so a	// failure that comes back after a device reset is reported again.	bool                 m_bMeterHistogramFailureLogged = false;	// Readback state. m_fMeterIssuedExposure is the pre-exposure that was in force for the frame	// whose sample is currently in flight: dividing by THAT, and not by the current one, is what	// stops the meter from being a two-frame-delayed feedback loop that oscillates.	bool  m_bMeterReadbackIssued  = false;	bool  m_bMeterReadbackStalled = false;	float m_fMeterIssuedExposure  = 1.0f;	float m_fMeterIssuedTime      = 0.0f;	// WHICH texture the download in flight belongs to, recorded at issue time: flipping	// r_SceneReferredMeterHistogram mid-flight must not decode 64 uints as two CryHalfs or the	// reverse. Also the metering mask the dispatch that produced it actually used.	bool   m_bMeterIssuedHistogram = false;	uint32 m_nMeterHistogramMode   = 0;	uint32 m_nMeterIssuedMode      = 0;	uint32 m_nMeterSampleId        = 0;};